async function fixture(){const f=await files();try{
 const file=await f.file();assert.equal((await f.serving()).response.status,200);const p=await f.request('community/profiles',{anchor:{kind:'hub',id:f.hub},definition:{content:{en:{displayName:'Synthetic image queue hub',headline:'Robotics'}},archived:false,avatar:{fileId:file.id,fileVersion:1,copyId:file.copyId}},reason:'Private reviewed image draft'});assert.equal(p.response.status,201,JSON.stringify(p.body));const id=p.body.data.id,path='community/profiles/'+id+'/image-release';assert.equal((await f.request('community/profiles/'+id+'/publication',{expectedVersion:0,expectedProfileVersion:1,audience:'public',reason:'Reviewed text-only release'})).response.status,200);
 const publish=()=>f.request(path,{expectedVersion:0,state:'published',selection:[{kind:'avatar',alt:{en:'Approved robotics logo'}}],reason:'Explicit reviewed image'}),database:Database={async connect(){const c=f.pg.runtime?await f.pg.runtime.connect():{query:f.pg.query.bind(f.pg),release(){}};await c.query('SET ROLE kavosh_profile_image_worker');return c;}};
 const run=async(callback:Parameters<typeof processOneProfileImage>[3],options:Parameters<typeof processOneProfileImage>[4]={})=>{try{return await processOneProfileImage(database,[f.a],randomUUID(),callback,options);}finally{if(!f.pg.runtime)await f.pg.exec('RESET ROLE');}};
 return{...f,file,id,path,publish,database,run};}catch(e){await f.pg.close();throw e;}}
const config={accountId:'a'.repeat(32),jurisdiction:'default' as const,bucket:'synthetic-durable-profile-copies',accessKeyId:'synthetic-image-job-writer',secretAccessKey:'synthetic-not-real-image-job-secret',maximumUploadBytes:4194304};
function storage(){const objects=new Map<string,Buffer>(),methods:string[]=[];return{objects,methods,handler:{destroy(){},async handle(request:{path:string;method:string;body?:unknown}){methods.push(request.method);if(request.method==='PUT'){assert.ok(Buffer.isBuffer(request.body));objects.set(request.path,Buffer.from(request.body));return{response:{statusCode:200,headers:{},body:Readable.from([])}};}const bytes=objects.get(request.path)!;return{response:{statusCode:200,headers:{etag:'"synthetic-job-readback"','content-type':'application/octet-stream','content-length':String(bytes.length)},body:Readable.from([bytes])}};}}};}
async function imageDelivery(f:Awaited<ReturnType<typeof fixture>>,optIn=true){
 const policy=await f.request('automations/delivery-policy');assert.equal((await f.request('automations/delivery-policy',{expectedVersion:policy.body.data.version,definition:{...policy.body.data.definition,enabled:true,maxDailyEmailRequests:10,maxDailySmsRequests:10,maxHourlyRequestsPerRecipient:10},reason:'Synthetic reviewed delivery policy'})).response.status,200);
 if(optIn){const previous=await f.request('me/notification-preferences');assert.ok([200,201].includes((await f.request('me/notification-preferences',{expectedVersion:previous.body.data.version,emailEnabled:true,smsEnabled:true,locale:'fr',acknowledgedNoticeVersion:1})).response.status));}
 const definition={name:'Image processing exceptions',enabled:true,trigger:{kind:'domain_event',eventTypes:['profile.image.processing.blocked.critical']},condition:{op:'eq',field:'severity',value:'critical'},actions:[{kind:'notify',channels:['portal','email','sms'],audience:{kind:'school_master'},severity:'inherit',title:{en:'Image processing needs review',fr:'Image à examiner'},body:{en:'Review the linked image processing case.',fr:'Examinez le suivi de traitement associé.'}}],execution:{mode:'automatic',maxRecipientsPerEvent:10,maxDailyDeliveries:10,maxDailySms:10,cooldownSeconds:0,maxChainDepth:1}},rule=await f.request('automations/rules',{hubId:f.hub,code:'IMAGE_FAILURES',definition,reason:'Synthetic reviewed image exception notices'});assert.equal(rule.response.status,201,JSON.stringify(rule.body));assert.equal((await f.publish()).response.status,200);assert.deepEqual(await f.run(async()=>({outcome:'rejected'})),{claimed:true,recorded:true});const incident=(await f.pg.query('SELECT id FROM public.profile_image_incidents')).rows[0].id,dispatch=()=>f.request('automations/rules/'+rule.body.data.id+'/dispatch',{eventId:incident,expectedVersion:1}),result=await dispatch();assert.equal(result.response.status,201,JSON.stringify({body:result.body,errors:f.metrics.queryFailures}));
 const sent:Array<{channel:string;text:string}>=[],transport:MessageTransport={channels:['email','sms'],async email(m){sent.push({channel:'email',text:m.text});return{provider:'smtp',providerMessageId:'<synthetic-image@example.test>',providerStatus:'accepted',providerAccepted:true,deliveryConfirmed:false};},async sms(m){sent.push({channel:'sms',text:m.text});return{provider:'twilio',providerMessageId:'SM'+'a'.repeat(32),providerStatus:'accepted',providerAccepted:true,deliveryConfirmed:false};}},database:Database={async connect(){const c=f.pg.runtime?await f.pg.runtime.connect():{query:f.pg.query.bind(f.pg),release(){}};await c.query('SET ROLE kavosh_message_worker');return c;}},work=async()=>{try{return await processOneMessage(database,[f.a],()=>transport);}finally{if(!f.pg.runtime)await f.pg.exec('RESET ROLE');}};
 return{incident,result,dispatch,sent,work,database};
}
test('actual418to419 preserves reviewed image and notice history and keeps sender source-lock authority trigger-only',async()=>{
 const f=await operationsFixture({throughSchema:418});try{const created=await f.request('community/profiles',{anchor:{kind:'hub',id:f.hub},definition:{content:{en:{displayName:'Historical reviewed image sharing'}},archived:false},reason:'Original hub draft'});assert.equal(created.response.status,201);assert.equal((await f.request('community/profiles/'+created.body.data.id+'/image-release',{expectedVersion:0,state:'withdrawn',selection:[],reason:'Original exact withdrawal'})).response.status,200);
  const snapshot=async()=>{const rows=[];for(const table of ['community_profiles','profile_image_releases','profile_image_jobs','profile_image_job_attempts','profile_image_incidents','approval_requests','audit_events','outbox_events','portal_notifications','role_permissions','notification_deliveries','operational_send_reservations'])rows.push((await f.pg.query('SELECT to_jsonb(t) r FROM public.'+table+' t ORDER BY to_jsonb(t)::text')).rows);return rows;},before=await snapshot(),functions="SELECT oid,proowner,proacl,proconfig FROM pg_proc WHERE oid=ANY(ARRAY['public.lock_notification_delivery_source(uuid,uuid)'::regprocedure,'public.image_processing_notice_allows(uuid,jsonb)'::regprocedure,'public.image_processing_notice_current(uuid)'::regprocedure]) ORDER BY oid",security=(await f.pg.query(functions)).rows;
  await f.pg.exec(await readFile(new URL('../db/migrations/419_profile_image_delivery.sql',import.meta.url),'utf8'));assert.equal((await f.pg.query('SELECT public.schema_revision() revision')).rows[0].revision,419);assert.deepEqual(await snapshot(),before);assert.deepEqual((await f.pg.query(functions)).rows,security);const guard=(await f.pg.query("SELECT r.rolname owner,p.prosecdef,has_function_privilege('kavosh_message_worker',p.oid,'EXECUTE') sender_exec,has_function_privilege('kavosh_message_worker','public.lock_image_processing_source(uuid)','EXECUTE') source_lock_exec FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.guard_image_processing_delivery()'::regprocedure")).rows[0];assert.deepEqual(guard,{owner:'kavosh_message_policy',prosecdef:true,sender_exec:false,source_lock_exec:false});await upgradeToCurrent(f.pg);
 }finally{await f.pg.close();}
});
