test('terminal processing creates one source-bound critical notice and reading never clears the retained blocked case',async()=>{
 const f=await fixture();try{assert.equal((await f.publish()).response.status,200);assert.deepEqual(await f.run(async()=>({outcome:'stored_bytes_mismatch'})),{claimed:true,recorded:true});const i=(await f.pg.query('SELECT * FROM public.profile_image_incidents')).rows[0];assert.equal(i.profile_id,f.id);assert.equal(i.reason_code,'stored_bytes_mismatch');assert.equal(i.attempt_no,1);
  const events=await f.request('automations/events?sourceKind=image_processing');assert.equal(events.response.status,200,JSON.stringify({body:events.body,errors:f.metrics.queryFailures}));assert.equal(events.body.data.length,1);assert.equal(events.body.data[0].sample.severity,'critical');assert.doesNotMatch(JSON.stringify(events.body),/storageTargetId|secretAccessKey|destinationEtag|lease_token|PRIVATE/);
  const notices=await f.request('notifications?origin=mandatory');assert.equal(notices.response.status,200,JSON.stringify({body:notices.body,errors:f.metrics.queryFailures}));const n=notices.body.data.find((n:any)=>n.source.kind==='image_processing');assert.ok(n,JSON.stringify(notices.body));assert.equal(n.severity,'critical');assert.equal(n.source.profileId,f.id);assert.equal(n.source.recordPath,'/api/v1/'+f.path+'/processing');assert.equal(n.source.caseResolvedByReading,false);assert.equal(n.source.attentionStillCurrent,true);assert.equal(n.source.customDeliveryEnabled,true);assert.equal((await f.request('notifications/'+n.id+'/read',{})).response.status,200);
  assert.equal((await f.request(f.path+'/processing')).body.data.jobs[0].state,'blocked');assert.deepEqual(await f.run(async()=>{throw Error('No terminal replay');}),{claimed:false,recorded:false});assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.profile_image_incidents')).rows[0].n,1);assert.equal((await f.request('notifications?origin=mandatory&locale=fr')).body.data.find((x:any)=>x.id===n.id).title,'Traitement de l’image du profil à examiner');
  assert.equal((await f.request(f.path,{expectedVersion:1,state:'withdrawn',selection:[],reason:'Withdraw the failed image edition'})).response.status,200);const old=(await f.request('notifications?origin=mandatory')).body.data.find((x:any)=>x.id===n.id);assert.equal(old.source.attentionStillCurrent,false);assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.profile_image_incidents')).rows[0].n,1);
 }finally{await f.pg.close();}
});
